 [76,-1,79,81,-1,79,76,74],[72,-1,76,-1,79,76,74,-1],
 [77,-1,81,79,-1,77,76,74],[74,-1,79,-1,83,81,79,-1],
 [76,79,-1,84,-1,81,79,76],[72,-1,76,79,-1,76,74,-1],
